using System.Globalization;

namespace AdsbCarMap.Data
{
    /// <summary>
    /// Airports and runways bundled with the application (Assets/Airports, generated by Scripts/Update-AirportData.ps1 from OurAirports data). Loaded once in the background into a grid index, so that the airports in the visible part of the map can be found quickly.
    /// </summary>
    public sealed partial class AirportDatabase
    {
        /// <summary>
        /// Number of columns of the airports file.
        /// </summary>
        private const int AirportColumns = 11;

        /// <summary>
        /// Number of columns of the runways file.
        /// </summary>
        private const int RunwayColumns = 11;

        /// <summary>
        /// Number of columns of the frequencies file.
        /// </summary>
        private const int FrequencyColumns = 4;

        /// <summary>
        /// Length of a runway in feet from which the airport counts as having a long runway, about 800 m.
        /// </summary>
        private const int LongRunwayFeet = 2625;

        /// <summary>
        /// Match quality of a query word that is exactly an ICAO or IATA code.
        /// </summary>
        public const int ExactMatch = 3;

        /// <summary>
        /// Match quality of a query word that starts a code, the name or the city, or one of their words.
        /// </summary>
        public const int PrefixMatch = 2;

        /// <summary>
        /// Match quality of a query word that is somewhere inside the searched text.
        /// </summary>
        public const int ContainsMatch = 1;

        /// <summary>
        /// All airports, sorted by size class and then by name.
        /// </summary>
        private Airport[] airports = Array.Empty<Airport>();

        /// <summary>
        /// Grid index: airports of every one-degree cell, in the order of <see cref="airports"/>.
        /// </summary>
        private Dictionary<int, int[]> grid = new Dictionary<int, int[]>();

        /// <summary>
        /// Airports by ICAO code, in upper case.
        /// </summary>
        private Dictionary<string, Airport> byIcao = new Dictionary<string, Airport>();

        /// <summary>
        /// Runways by the ICAO code of the airport, in upper case.
        /// </summary>
        private Dictionary<string, Runway[]> runways = new Dictionary<string, Runway[]>();

        /// <summary>
        /// Frequencies by the ICAO code of the airport, in upper case.
        /// </summary>
        private Dictionary<string, AirportFrequency[]> frequencies = new Dictionary<string, AirportFrequency[]>();

        /// <summary>
        /// Non-zero when the data is ready to use.
        /// </summary>
        private int loaded;

        /// <summary>
        /// Non-zero when the frequencies have been loaded, which happens after the airports and runways are ready.
        /// </summary>
        private int frequenciesLoaded;

        /// <summary>
        /// Event raised on a background thread when the airports and runways have been loaded, which is the moment the airports can be drawn.
        /// </summary>
        public event System.Action? Loaded;

        /// <summary>
        /// Event raised on a background thread when the frequencies have been loaded, after <see cref="Loaded"/>.
        /// </summary>
        public event System.Action? FrequenciesLoaded;

        /// <summary>
        /// Whether the data is ready to use.
        /// </summary>
        public bool IsLoaded => Volatile.Read(ref loaded) != 0;

        /// <summary>
        /// Whether the frequencies are ready; before that <see cref="GetFrequencies"/> returns none.
        /// </summary>
        public bool AreFrequenciesLoaded => Volatile.Read(ref frequenciesLoaded) != 0;

        /// <summary>
        /// Total number of airports, or 0 before the data is loaded.
        /// </summary>
        public int Count => airports.Length;
        /// <summary>
        /// Removes diacritics and changes the text to lower case, so that "Kraków" can be found with "krakow".
        /// </summary>
        /// <param name="text">Text to normalize.</param>
        /// <returns>Lower-case text without diacritics.</returns>
        public static string Fold(string text)
        {
            return TextFolding.Fold(text);
        }

        /// <summary>
        /// Adds the airports located in a rectangle and ranked at most as the given size class to a list, biggest first.
        /// </summary>
        /// <param name="minLatitude">Southern edge.</param>
        /// <param name="maxLatitude">Northern edge.</param>
        /// <param name="minLongitude">Western edge.</param>
        /// <param name="maxLongitude">Eastern edge.</param>
        /// <param name="smallestType">Smallest size class to include.</param>
        /// <param name="result">List that receives the airports.</param>
        public void Query(double minLatitude, double maxLatitude, double minLongitude, double maxLongitude, AirportType smallestType, List<Airport> result)
        {
            Query(minLatitude, maxLatitude, minLongitude, maxLongitude, airport => airport.Type <= smallestType, result);
        }

        /// <summary>
        /// Adds the airports located in a rectangle and accepted by a filter to a list.
        /// </summary>
        /// <param name="minLatitude">Southern edge.</param>
        /// <param name="maxLatitude">Northern edge.</param>
        /// <param name="minLongitude">Western edge.</param>
        /// <param name="maxLongitude">Eastern edge.</param>
        /// <param name="filter">Decides whether an airport is added.</param>
        /// <param name="result">List that receives the airports.</param>
        public void Query(double minLatitude, double maxLatitude, double minLongitude, double maxLongitude, Predicate<Airport> filter, List<Airport> result)
        {
            if (!IsLoaded)
            {
                return;
            }

            int firstRow = (int)Math.Floor(Math.Clamp(minLatitude, -90.0, 90.0));
            int lastRow = (int)Math.Floor(Math.Clamp(maxLatitude, -90.0, 90.0));
            int firstColumn = (int)Math.Floor(Math.Clamp(minLongitude, -180.0, 179.999));
            int lastColumn = (int)Math.Floor(Math.Clamp(maxLongitude, -180.0, 179.999));

            for (int row = firstRow; row <= lastRow; row++)
            {
                for (int column = firstColumn; column <= lastColumn; column++)
                {
                    if (!grid.TryGetValue(GetCell(row, column), out int[]? indexes))
                    {
                        continue;
                    }

                    foreach (int index in indexes)
                    {
                        Airport airport = airports[index];

                        if (filter(airport)
                            && airport.Latitude >= minLatitude && airport.Latitude <= maxLatitude
                            && airport.Longitude >= minLongitude && airport.Longitude <= maxLongitude)
                        {
                            result.Add(airport);
                        }
                    }
                }
            }
        }

        /// <summary>
        /// Finds an airport by its ICAO or IATA code.
        /// </summary>
        /// <param name="code">Code in any letter case.</param>
        /// <returns>The airport, or null when there is none with this code.</returns>
        public Airport? Find(string? code)
        {
            if (string.IsNullOrWhiteSpace(code) || !IsLoaded)
            {
                return null;
            }

            string key = code.Trim().ToUpperInvariant();

            if (byIcao.TryGetValue(key, out Airport? airport))
            {
                return airport;
            }

            foreach (Airport candidate in airports)
            {
                if (candidate.Iata.Length > 0 && string.Equals(candidate.Iata, key, StringComparison.OrdinalIgnoreCase))
                {
                    return candidate;
                }
            }

            return null;
        }

        /// <summary>
        /// Finds an airport by its ICAO code only. Faster than <see cref="Find"/>, which also looks at IATA codes.
        /// </summary>
        /// <param name="icao">ICAO code in any letter case.</param>
        /// <returns>The airport, or null when there is none with this code.</returns>
        public Airport? FindByIcao(string icao)
        {
            return IsLoaded && byIcao.TryGetValue(icao.Trim().ToUpperInvariant(), out Airport? airport) ? airport : null;
        }

        /// <summary>
        /// Tells whether a runway surface code means a paved surface (asphalt, concrete, bitumen and the like).
        /// </summary>
        /// <param name="surface">Surface code from the data, for example ASPH or CON.</param>
        /// <returns>True for a paved surface.</returns>
        private static bool IsPaved(string surface)
        {
            string code = surface.Trim().ToUpperInvariant();

            return code.StartsWith("ASP", StringComparison.Ordinal)
                || code.StartsWith("CON", StringComparison.Ordinal)
                || code.StartsWith("PEM", StringComparison.Ordinal)
                || code.StartsWith("BIT", StringComparison.Ordinal)
                || code.StartsWith("PAV", StringComparison.Ordinal)
                || code.StartsWith("TAR", StringComparison.Ordinal);
        }

        /// <summary>
        /// Returns the radio frequencies of an airport.
        /// </summary>
        /// <param name="airport">Airport.</param>
        /// <returns>Frequencies in the order of the file, possibly none.</returns>
        public IReadOnlyList<AirportFrequency> GetFrequencies(Airport airport)
        {
            return frequencies.TryGetValue(airport.Icao.ToUpperInvariant(), out AirportFrequency[]? list) ? list : Array.Empty<AirportFrequency>();
        }

        /// <summary>
        /// Returns the runways of an airport.
        /// </summary>
        /// <param name="airport">Airport.</param>
        /// <returns>Runways with coordinates, possibly none.</returns>
        public IReadOnlyList<Runway> GetRunways(Airport airport)
        {
            return runways.TryGetValue(airport.Icao.ToUpperInvariant(), out Runway[]? list) ? list : Array.Empty<Runway>();
        }

        /// <summary>
        /// Rates how well an airport matches the words of a query: the weakest match among the words, or 0 when some word does not match.
        /// </summary>
        /// <param name="airport">Airport.</param>
        /// <param name="terms">Words of the query, already folded with <see cref="Fold"/>.</param>
        /// <returns>0 for no match, otherwise <see cref="ContainsMatch"/>, <see cref="PrefixMatch"/> or <see cref="ExactMatch"/>.</returns>
        public static int GetMatchQuality(Airport airport, IReadOnlyList<string> terms)
        {
            int quality = ExactMatch;

            foreach (string term in terms)
            {
                int termQuality = GetTermQuality(airport, term);

                if (termQuality == 0)
                {
                    return 0;
                }

                quality = Math.Min(quality, termQuality);
            }

            return terms.Count == 0 ? 0 : quality;
        }

        /// <summary>
        /// Returns the airports matching a query, best matches first. Used by the combined search of aircraft and airports.
        /// </summary>
        /// <param name="terms">Words of the query, already folded with <see cref="Fold"/>.</param>
        /// <param name="maxResults">Maximum number of airports.</param>
        /// <param name="includeHeliports">Whether heliports are listed. Thousands of them match common words, so they are listed only when they are shown on the map or the query is exactly their code.</param>
        /// <param name="isPreferred">Tells which airports (the favorites) come first among equally good matches, or null.</param>
        /// <returns>Matching airports with the match quality of each.</returns>
        public List<(Airport Airport, int Quality)> Search(IReadOnlyList<string> terms, int maxResults, bool includeHeliports, Func<Airport, bool>? isPreferred = null)
        {
            List<(Airport Airport, int Quality)> result = new List<(Airport Airport, int Quality)>();

            if (!IsLoaded || terms.Count == 0)
            {
                return result;
            }

            foreach (Airport airport in airports)
            {
                int quality = GetMatchQuality(airport, terms);

                if (quality > 0 && (includeHeliports || airport.Type != AirportType.Heliport || quality == ExactMatch))
                {
                    result.Add((airport, quality));
                }
            }

            return result
                .OrderByDescending(item => item.Quality)
                .ThenByDescending(item => isPreferred != null && isPreferred(item.Airport))
                .ThenBy(item => item.Airport.Type)
                .ThenByDescending(item => item.Airport.HasScheduledService)
                .ThenBy(item => item.Airport.Name, StringComparer.OrdinalIgnoreCase)
                .Take(maxResults)
                .ToList();
        }

        /// <summary>
        /// Returns the airports closest to a point.
        /// </summary>
        /// <param name="latitude">Latitude of the point.</param>
        /// <param name="longitude">Longitude of the point.</param>
        /// <param name="count">Number of airports.</param>
        /// <param name="smallestType">Smallest size class to include.</param>
        /// <returns>The closest airports, closest first.</returns>
        public List<Airport> GetNearest(double latitude, double longitude, int count, AirportType smallestType)
        {
            List<Airport> result = new List<Airport>();

            if (!IsLoaded)
            {
                return result;
            }

            for (double span = 1.0; span <= 32.0 && result.Count < count; span *= 2.0)
            {
                result.Clear();
                Query(latitude - span, latitude + span, longitude - span, longitude + span, smallestType, result);
            }

            return result
                .OrderBy(item => GeoMath.DistanceKilometers(latitude, longitude, item.Latitude, item.Longitude))
                .Take(count)
                .ToList();
        }

        /// <summary>
        /// Rates one word of a query against an airport.
        /// </summary>
        /// <param name="airport">Airport.</param>
        /// <param name="term">Folded word.</param>
        /// <returns>0 for no match, or the match quality.</returns>
        private static int GetTermQuality(Airport airport, string term)
        {
            if (string.Equals(airport.Icao, term, StringComparison.OrdinalIgnoreCase) || string.Equals(airport.Iata, term, StringComparison.OrdinalIgnoreCase))
            {
                return ExactMatch;
            }

            string text = airport.SearchText;
            int position = text.IndexOf(term, StringComparison.Ordinal);

            if (position < 0)
            {
                return 0;
            }

            while (position >= 0)
            {
                if (position == 0 || text[position - 1] == ' ' || text[position - 1] == '-')
                {
                    return PrefixMatch;
                }

                position = text.IndexOf(term, position + 1, StringComparison.Ordinal);
            }

            return ContainsMatch;
        }

        /// <summary>
        /// Number of runways, or 0 before the data is loaded.
        /// </summary>
        public int RunwayCount => runways.Values.Sum(item => item.Length);

        /// <summary>
        /// Builds all the indexes: the airports and runways first, then the frequencies. Invalid lines are skipped.
        /// </summary>
        /// <param name="airportLines">Tab separated lines of the airports file.</param>
        /// <param name="runwayLines">Tab separated lines of the runways file.</param>
        /// <param name="frequencyLines">Tab separated lines of the frequencies file, or null when there are none.</param>
        public void LoadFrom(IEnumerable<string> airportLines, IEnumerable<string> runwayLines, IEnumerable<string>? frequencyLines = null)
        {
            LoadAirports(airportLines, runwayLines);
            LoadFrequencies(frequencyLines);
        }

        /// <summary>
        /// Builds the indexes of the airports and runways and marks the data as ready, so that the airports can be drawn and searched. The frequencies are not needed for that and are loaded later by <see cref="LoadFrequencies"/>. Invalid lines are skipped.
        /// </summary>
        /// <param name="airportLines">Tab separated lines of the airports file.</param>
        /// <param name="runwayLines">Tab separated lines of the runways file.</param>
        public void LoadAirports(IEnumerable<string> airportLines, IEnumerable<string> runwayLines)
        {
            Airport[] sorted = airportLines
                .AsParallel()
                .AsOrdered()
                .Select(ParseAirport)
                .Where(item => item != null)
                .Select(item => item!)
                .ToArray()
                .OrderBy(item => item.Type)
                .ThenByDescending(item => item.HasScheduledService)
                .ThenBy(item => item.Name, StringComparer.Ordinal)
                .ToArray();

            Dictionary<int, List<int>> cells = new Dictionary<int, List<int>>();
            Dictionary<string, Airport> codes = new Dictionary<string, Airport>();

            for (int index = 0; index < sorted.Length; index++)
            {
                Airport airport = sorted[index];
                int cell = GetCell((int)Math.Floor(airport.Latitude), (int)Math.Floor(Math.Min(airport.Longitude, 179.999)));

                if (!cells.TryGetValue(cell, out List<int>? members))
                {
                    members = new List<int>();
                    cells[cell] = members;
                }

                members.Add(index);
                codes.TryAdd(airport.Icao.ToUpperInvariant(), airport);
            }

            Dictionary<string, List<Runway>> runwayLists = new Dictionary<string, List<Runway>>();

            foreach ((string Key, Runway Runway) item in runwayLines
                .AsParallel()
                .AsOrdered()
                .Select(ParseRunwayLine)
                .Where(item => item.HasValue)
                .Select(item => item!.Value)
                .ToArray())
            {
                if (!runwayLists.TryGetValue(item.Key, out List<Runway>? runwayList))
                {
                    runwayList = new List<Runway>();
                    runwayLists[item.Key] = runwayList;
                }

                runwayList.Add(item.Runway);
            }

            airports = sorted;
            grid = cells.ToDictionary(item => item.Key, item => item.Value.ToArray());
            byIcao = codes;
            runways = runwayLists.ToDictionary(item => item.Key, item => item.Value.ToArray());

            foreach (KeyValuePair<string, List<Runway>> pair in runwayLists)
            {
                if (codes.TryGetValue(pair.Key, out Airport? owner))
                {
                    owner.SetLongPavedRunway(pair.Value.Any(runway => runway.LengthFeet >= LongRunwayFeet && IsPaved(runway.Surface)));
                }
            }

            Volatile.Write(ref loaded, 1);
            Loaded?.Invoke();
        }

        /// <summary>
        /// Builds the index of the radio frequencies. Until it is built <see cref="GetFrequencies"/> returns no frequencies. Invalid lines are skipped.
        /// </summary>
        /// <param name="frequencyLines">Tab separated lines of the frequencies file, or null when there are none.</param>
        public void LoadFrequencies(IEnumerable<string>? frequencyLines)
        {
            Dictionary<string, List<AirportFrequency>> frequencyLists = new Dictionary<string, List<AirportFrequency>>();

            foreach ((string Key, AirportFrequency Frequency) item in (frequencyLines ?? Array.Empty<string>())
                .AsParallel()
                .AsOrdered()
                .Select(ParseFrequencyLine)
                .Where(item => item.HasValue)
                .Select(item => item!.Value)
                .ToArray())
            {
                if (!frequencyLists.TryGetValue(item.Key, out List<AirportFrequency>? frequencyList))
                {
                    frequencyList = new List<AirportFrequency>();
                    frequencyLists[item.Key] = frequencyList;
                }

                frequencyList.Add(item.Frequency);
            }

            frequencies = frequencyLists.ToDictionary(item => item.Key, item => item.Value.ToArray());
            Volatile.Write(ref frequenciesLoaded, 1);
            FrequenciesLoaded?.Invoke();
        }

        /// <summary>
        /// Converts a line of the airports file to an airport.
        /// </summary>
        /// <param name="line">Tab separated line.</param>
        /// <returns>The airport, or null when the line is not valid.</returns>
        private static Airport? ParseAirport(string line)
        {
            string[] fields = line.Split('\t');

            if (fields.Length < AirportColumns
                || !double.TryParse(fields[6], NumberStyles.Float, CultureInfo.InvariantCulture, out double latitude)
                || !double.TryParse(fields[7], NumberStyles.Float, CultureInfo.InvariantCulture, out double longitude))
            {
                return null;
            }

            AirportType type = fields[2] == "L" ? AirportType.Large : fields[2] == "M" ? AirportType.Medium : fields[2] == "H" ? AirportType.Heliport : AirportType.Small;
            int? elevation = int.TryParse(fields[8], NumberStyles.Integer, CultureInfo.InvariantCulture, out int parsedElevation) ? parsedElevation : null;

            return new Airport(fields[0], fields[1], type, fields[3], fields[4], fields[5], latitude, longitude, elevation, fields[9] == "1", fields[10] == "1");
        }

        /// <summary>
        /// Converts the fields of a line of the runways file to a runway.
        /// </summary>
        /// <param name="fields">Fields of the line.</param>
        /// <returns>The runway, or null when the coordinates are not valid.</returns>
        private static Runway? ParseRunway(string[] fields)
        {
            if (!double.TryParse(fields[6], NumberStyles.Float, CultureInfo.InvariantCulture, out double lowLatitude)
                || !double.TryParse(fields[7], NumberStyles.Float, CultureInfo.InvariantCulture, out double lowLongitude)
                || !double.TryParse(fields[9], NumberStyles.Float, CultureInfo.InvariantCulture, out double highLatitude)
                || !double.TryParse(fields[10], NumberStyles.Float, CultureInfo.InvariantCulture, out double highLongitude))
            {
                return null;
            }

            int.TryParse(fields[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out int length);
            int.TryParse(fields[2], NumberStyles.Integer, CultureInfo.InvariantCulture, out int width);

            return new Runway(length, width, fields[3], fields[4] == "1", fields[5], lowLatitude, lowLongitude, fields[8], highLatitude, highLongitude);
        }

        /// <summary>
        /// Converts a line of the runways file to a runway with the code of its airport.
        /// </summary>
        /// <param name="line">Tab separated line.</param>
        /// <returns>The airport code in upper case and the runway, or null when the line is not valid.</returns>
        private static (string Key, Runway Runway)? ParseRunwayLine(string line)
        {
            string[] fields = line.Split('\t');

            if (fields.Length < RunwayColumns)
            {
                return null;
            }

            Runway? runway = ParseRunway(fields);

            return runway == null ? null : (fields[0].ToUpperInvariant(), runway);
        }

        /// <summary>
        /// Converts a line of the frequencies file to a frequency with the code of its airport.
        /// </summary>
        /// <param name="line">Tab separated line.</param>
        /// <returns>The airport code in upper case and the frequency, or null when the line is not valid.</returns>
        private static (string Key, AirportFrequency Frequency)? ParseFrequencyLine(string line)
        {
            string[] fields = line.Split('\t');

            if (fields.Length < FrequencyColumns
                || !double.TryParse(fields[3], NumberStyles.Float, CultureInfo.InvariantCulture, out double megahertz)
                || megahertz <= 0.0)
            {
                return null;
            }

            return (fields[0].ToUpperInvariant(), new AirportFrequency(fields[1].Trim().ToUpperInvariant(), fields[2], megahertz));
        }

        /// <summary>
        /// Returns the key of a one-degree grid cell.
        /// </summary>
        /// <param name="row">Whole degrees of latitude.</param>
        /// <param name="column">Whole degrees of longitude.</param>
        /// <returns>Key of the cell.</returns>
        private static int GetCell(int row, int column)
        {
            return (row + 90) * 360 + (column + 180);
        }
    }
}
